// LED province -> TD province (whole-province moves only)
const PROV = { "97": "38" };

let fullEntries = null;
try {
  fullEntries = JSON.parse(
    fs.readFileSync(path.join(__dirname, "led_to_td_map.json"), "utf8")
  ).entries;
} catch { /* sidecar optional */ }

/**
 * Map one LED district to its TD counterpart.
 * @param {string} ledProvinceCode  2-digit LED province code, e.g. "10"
 * @param {string} ledDistrictCode  4-digit composite ("1040") or 2-digit amphoe ("40")
 * @returns {null|object} null if unknown / no counterpart (4 dissolved districts)
 */
function ledToTd(ledProvinceCode, ledDistrictCode) {
  const prov = String(ledProvinceCode).trim().padStart(2, "0");
  let d = String(ledDistrictCode).trim();
  if (d.length <= 2) d = prov + d.padStart(2, "0");
  d = d.padStart(4, "0");
  const hit = MAP[d];
  if (!hit) return null;
  const [ledName, tdName] = NAMES[d] || ["", ""];
  const out = {
    ledProvinceCode: prov,
    ledDistrictCode: d,
    ledDistrictName: ledName,
    tdProvinceCode: hit[0],
    tdDistrictCode: hit[1],
    tdDistrictComposite: hit[2],
    tdDistrictName: tdName,
  };
  if (fullEntries) {
    const e = fullEntries.find((x) => x.led_district_code === d);
    if (e) {
      out.matchMethod = e.match_method;
      out.note = e.note;
    }
  }
  return out;
}

/** Province-level mapping (identity except 97->38). For districts ALWAYS use ledToTd(). */
function ledProvinceToTd(ledProvinceCode) {
  const prov = String(ledProvinceCode).trim().padStart(2, "0");
  return PROV[prov] || prov;
}

module.exports = { ledToTd, ledProvinceToTd, MAP };

if (require.main === module) {
  const [, , p, d] = process.argv;
  if (!p || !d) {
    console.log("usage: node led_to_td.js <ledProvinceCode> <ledDistrictCode>");
    console.log('  e.g. node led_to_td.js 10 1040   # LED สายไหม -> TD 1042');
    process.exit(2);
  }
  const r = ledToTd(p, d);
  if (!r) {
    console.log("No TD counterpart for this LED code");
    process.exit(1);
  }
  console.log(
    `LED ${r.ledProvinceCode}/${r.ledDistrictCode} ${r.ledDistrictName}  ->  ` +
    `TD ${r.tdProvinceCode}+${r.tdDistrictCode} (${r.tdDistrictComposite}) ${r.tdDistrictName}`
  );
  if (r.note) console.log(`  [${r.matchMethod}] ${r.note}`);
}
